/* One listening report at a time; original prompts and recordings are unchanged. */
(()=>{
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const position=(s,u)=>Math.max(0,Math.min(u.passages.length-1,Number(s.drafts['listen:'+u.id+':position'])||0));
 function guide(host,{state:s,unit:u,units,onStart,onUnit}){host.innerHTML=`<div class="journey-heading"><div><div class="eyebrow">LISTENING · LEARN THEN PRACTISE</div><h1>先掌握方法，再逐篇闯关。</h1><p>全部使用资料中的新闻题目与原始录音，不换成自编听力。</p></div></div><div class="toolbar"><label>选择单元 <select id="guide-unit">${units.map(x=>`<option value="${x.id}" ${x.id===u.id?'selected':''}>Unit ${x.id}</option>`).join('')}</select></label><span class="tag">${u.passages.length} 篇新闻 · ${u.passages.flatMap(p=>p.questions).length} 个原题填空</span></div><div class="panel listening-intro"><div class="card-kicker">UNIT ${u.id} · 准备站</div><h2>听力这关，分三步。</h2>${[['盲听，抓住上下文','先听本单元原音。每次只显示一篇新闻，把听清的词或短语写进空格。'],['提交，马上看到差距','每篇独立提交并逐空核对。不会的空可以留空；提交前至少尝试填写一空。'],['回听，修复还没听清的地方','用回退、调速和 A–B 循环精听。错空会进入错题本，再开始下一篇。']].map(([a,b],i)=>`<div class="listen-guide-step"><span>${i+1}</span><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}<div class="notice">原始音频是整单元录音，尚无可靠逐篇时间标记；切换新闻不会自动跳到对应时间，请使用播放器定位。</div><div class="button-row"><button class="primary" id="enter-listening">开始 Unit ${u.id} 原题挑战 →</button><button class="secondary" data-go="writing">返回教材章节</button></div></div>`;host.querySelector('#guide-unit').onchange=e=>onUnit(Number(e.target.value));host.querySelector('#enter-listening').onclick=()=>{s.drafts['listen:'+u.id+':mode']='practice';onStart()}}
 function mount(host,ctx){const{s,u}=ctx,i=position(s,u),sections=[...host.querySelectorAll('.listening-passage')];sections.forEach((section,k)=>section.hidden=k!==i);const first=sections[0];if(!first)return;const bar=document.createElement('div');bar.className='listening-route';bar.innerHTML=`<div class="passage-step-head"><span class="tag">原题关卡 ${i+1} / ${sections.length}</span><button class="quiet" id="listen-guide">← 学习方法</button></div><div class="passage-steps">${sections.map((_,k)=>`<button data-listen-step="${k}" class="${k===i?'active':''} ${s.results['listen-part-'+u.id+'-'+k]?'done':''}" aria-label="新闻第${k+1}篇">${k+1}</button>`).join('')}</div>`;first.before(bar);const nav=document.createElement('div');nav.className='listening-nav';nav.innerHTML=`<button class="secondary" id="listen-previous" ${i===0?'disabled':''}>← 上一篇</button><button class="primary" id="listen-next">${i===sections.length-1?'完成本轮，查看错题':'下一篇 →'}</button>`;host.querySelector('#submit-listening').closest('.button-row').after(nav);host.querySelector('#submit-listening').textContent='提交本篇，立即核对';host.querySelector('#retry-listening').textContent='重练这一篇';host.querySelector('.progress-text').textContent=`本篇 ${u.passages[i].questions.length} 空`;const select=k=>{s.drafts['listen:'+u.id+':position']=String(k);ctx.save();ctx.render();host.scrollIntoView({block:'start',behavior:'auto'})};host.querySelectorAll('[data-listen-step]').forEach(b=>b.onclick=()=>select(Number(b.dataset.listenStep)));host.querySelector('#listen-previous').onclick=()=>select(i-1);host.querySelector('#listen-next').onclick=()=>{if(!s.results['listen-part-'+u.id+'-'+i]){ctx.toast('先提交本篇，看看哪些空已经掌握。');return}if(i===sections.length-1)location.hash='mistakes';else select(i+1)};host.querySelector('#listen-guide').onclick=()=>{s.drafts['listen:'+u.id+':mode']='learn';ctx.save();ctx.render()};const r=s.results['listen-part-'+u.id+'-'+i];if(r)host.querySelector('#listen-score').innerHTML=`<p class="hint">本篇上次核对 ${r.score} / ${r.total}。可继续修订后重新提交。</p>`}
 function aggregate(s,u){const rs=u.passages.map((_,i)=>s.results['listen-part-'+u.id+'-'+i]).filter(Boolean);s.results['unit-'+u.id]={score:rs.reduce((n,r)=>n+r.score,0),total:u.passages.flatMap(p=>p.questions).length,date:new Date().toLocaleDateString('sv-SE'),attemptedPassages:rs.length}}
 window.ListeningFlow={position,guide,mount,aggregate,shouldPractice:(s,u)=>s.drafts['listen:'+u.id+':mode']==='practice'};
})();
